Section Stage.
Context {SCFG_P : ScfgP}.
Variables (L : asan_layout) (ar : asan_run) (C : asan_statics_cells) (IL : icpt_layout) (HI : asan_iface).
Hypothesis LY : PMB.layout L C.
Hypothesis HIok : HAJ.asan_iface_okR L ar C SCFG HI.
Let LYa := PMB.ly_as0 L C LY.

(* [comment removed for export] *)
Definition kont_c (R0 : bvmap 5 word) (M0 : word -> option byte) (model0 : Model) (K : TSet) (LB : list (Z * Z)) (FF LK0 : list fframe) (Aw0 : list (Z * Z)) (cr : credit)
    (ois sp r : Z) (s : PM.vstr) (b : bool) (l : list Z) : Prop :=
  forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z)) (s' : PM.vstr) (sm : PM.strm) (cr' : credit),
    regs_preserved R0 R' -> PMBIS.iss_at M' ois s' sm -> PM.vs_size s' = PM.vs_size s ->
    PM.sm_g sm = PM.vs_data (ois + 80) s' -> PM.sm_st sm = 0 ->
    L5.bytes_at RSEGS M' (PM.vs_data (ois + 80) s') l ->
    PMST.loc_ok RSEGS PMB.AD M' true ->
    L5CA.ahpres L ar LB FF sp (PMSPA.pm_scr 4) (PMBIS.WF ois b) M0 M' ->
    PMSPA.credit_keep cr cr' (PMBIS.cost L ar s) PMSPA.cr0 ->
    model_rt model0 model' -> incl LK' LK0 -> incl Aw0 Aw' -> L5CA.amodel_ok Aw' model' -> ri_inv HI (PM.vs_own s' ++ LB) FF LK' cr' Aw' M' (vml_of model') ->
    srealizes RSEGS SCFG (PMSPA.cfg RSEGS (fx:=fx') R' r M' model') K.

Theorem short_c : forall (fx : FPState) R0 M0 model0 K LB FF LK0 Aw0 cr ois os sp r n b R2 M2 model2 LK2 Aw2 (l : list Z),
    PMBIS.pre L ar HI R0 M0 model0 K LB FF LK0 Aw0 cr ois os sp r (PM.VShort n) b ->
    kont_c R0 M0 model0 K LB FF LK0 Aw0 cr ois sp r (PM.VShort n) b l ->
    Z.of_nat (length l) = n -> L5.bytes_at RSEGS M0 (os + 1) l ->
    PMBIS.mid2 L ar HI R0 M0 model0 LB FF LK0 Aw0 cr ois os sp (PM.VShort n) b R2 M2 model2 LK2 Aw2 ->
    srealizes RSEGS SCFG (PMSPA.cfg RSEGS (fx:=fx) R2 0xab41c M2 model2) K.
Proof.
Ltac a64 AG X Ms := apply (L5C.u64_at_agree RSEGS Ms); [intros i Hi; apply AG; (lia || fail 1 "AG")| (lia || fail 1 "B1")| (lia || fail 1 "B2")| exact X].
Ltac a32 AG X Ms := apply (PMF.u32_at_agree RSEGS Ms); [intros i Hi; apply AG; (lia || fail 1 "AG")| (lia || fail 1 "B1")| (lia || fail 1 "B2")| exact X].
